/**
 * Look up book reading content by ISBN or Title.
 * Works seamlessly offline during local presentations.
 */
export function getBookContent(identifier?: string | null): BookContentData | null {
  if (!identifier) return null;
  const clean = identifier.replace(/[\s-]/g, "").toLowerCase();
  
  if (BOOK_CONTENT_MAP[clean]) {
    return BOOK_CONTENT_MAP[clean];
  }

  // Fallback by title match
  const titleKey = identifier.trim().toLowerCase();
  if (BOOK_CONTENT_MAP[titleKey]) {
    return BOOK_CONTENT_MAP[titleKey];
  }

  return null;
}
